contract VestingContract {
    // Define the beneficiary address
    address public beneficiary;

    // Define the cliff time in seconds
    uint256 public cliffTime;

    // Define the vesting period in seconds
    uint256 public vestingPeriod;

    // Define the amount of ETH to be vested
    uint256 public amount;

    // Define a mapping to keep track of the vesting progress
    mapping(address => uint256) public vestingProgress;

    // Constructor to initialize the vesting contract
    constructor(address _beneficiary, uint256 _cliffTime, uint256 _vestingPeriod, uint256 _amount) {
        beneficiary = _beneficiary;
        cliffTime = _cliffTime;
        vestingPeriod = _vestingPeriod;
        amount = _amount;
    }

    // Function to claim the vested ETH
    function claim() public {
        // Check if the current time is after the cliff time
        if (block.timestamp >= cliffTime) {
            // Check if the vesting progress is less than the vesting period
            if (vestingProgress[msg.sender] < vestingPeriod) {
                // Calculate the amount to be vested
                uint256 vestedAmount = amount * (block.timestamp - cliffTime) / vestingPeriod;
                // Update the vesting progress
                vestingProgress[msg.sender] = vestingPeriod;
                // Transfer the vested ETH to the beneficiary
                payable(beneficiary).transfer(vestedAmount);
            } else {
                // If the vesting progress is already equal to the vesting period, the claim is complete
                payable(beneficiary).transfer(amount);
            }
        } else {
            // If the current time is before the cliff time, the claim is not complete
            revert("Claim not yet reached the cliff time");
        }
    }
}
```

